// Follow pointers with a visited set.
function fatChain(fat, start) {
  const chain = []; const thay = {};
  let b = start;
  while (b !== -1) {
    if (b < 0 || b >= fat.length || thay[b]) return { chain, ok: false };
    thay[b] = true; chain.push(b); b = fat[b];
  }
  return { chain, ok: true };
}
